document.addEventListener('click',event=>{if(event.target.closest('.skip-link')){event.preventDefault();app.focus();return;}const button=event.target.closest('[data-action],[data-route]');if(!button||button.disabled)return;if(button.dataset.route){navigate(button.dataset.route);if(route.page==='discover'&&state.catalogSignature!==catalogSignature())refreshCatalog();return;}actions[button.dataset.action]?.(button);});

document.addEventListener('submit',async event=>{
  if(event.target.id==='history-match-form'){event.preventDefault();await runHistoricalMatch(event.target);return;}
  if(['home-search-form','search-form'].includes(event.target.id)){event.preventDefault();const query=String(new FormData(event.target).get('query')||'').slice(0,80),inferred=inferCatalogUnit(query,catalogUnits());state={...state,preferences:{...state.preferences,query,...(inferred?{unit_id:inferred}:{})},matches:null};persist();navigate('/discover',{replace:route.page==='discover'});await refreshCatalog();return;}
  if(event.target.id!=='preferences-form')return;event.preventDefault();const form=event.target;if(!form.checkValidity()){prefTab('filters');form.reportValidity();return;}const data=new FormData(form),examCount=Number(data.get('examCount'))||4;
  const selected=draftSubjects.filter(subject=>subject.exam_unit<=examCount).map(subject=>({code:subject.code,name:subject.name,scope:subject.scope,exam_unit:subject.exam_unit})).toSorted((a,b)=>a.exam_unit-b.exam_unit);
  const planPath=route.page==='plan'&&workbenchTool()?location.hash.slice(1):'';const fee=data.get('max_annual_tuition'),studyMode=String(data.get('study_mode')||'');const profile={target_year:state.profile.target_year,reference_year:referenceYear(),education:data.get('education')||'unknown',background:String(data.get('background')||'').slice(0,120),subjects:selected,ranking_mode:String(data.get('priority')||'balanced'),preferences:{...weights[data.get('priority')||'balanced']},...(fee!==''?{max_annual_tuition:Number(fee)}:{}),...(studyMode?{study_mode:studyMode}:{}),...(data.get('max_subject_changes')!==''?{max_subject_changes:Number(data.get('max_subject_changes'))}:{})};
  state={...state,profile,preferences:{...state.preferences,unit_id:String(data.get('unit_id')||''),priority:String(data.get('priority')||'balanced'),examCount},matches:null,evaluations:new Map()};const stored=persist();applyPrograms();closeDialog(document,'preferences-dialog');navigate(planPath||'/discover',{replace:route.page==='discover'});if(planPath){toast(stored?'条件已保存，工作台已按新条件刷新。':'条件已应用，但浏览器未允许本地保存。');return;}await refreshCatalog();if(state.preferences.unit_id||ready())await runAnalysis();else toast(stored?'条件已保存。请选择学校后分析限定范围。':'条件已应用，但浏览器未允许本地保存。');
});
document.addEventListener('input',event=>{
  if(event.target.id==='search-input'){clearTimeout(searchTimer);++listSequence;++analysisSequence;state={...state,analyzing:false,preferences:{...state.preferences,query:event.target.value.slice(0,80)},matches:null,listLoading:true,error:''};persist();history.replaceState(null,'','#/discover');document.getElementById('results').innerHTML=results();document.querySelector('[data-action="analyze"]').disabled=true;searchTimer=setTimeout(refreshCatalog,240);}
  if(event.target.id==='subject-search'){clearTimeout(subjectTimer);const query=event.target.value.slice(0,80);subjectTimer=setTimeout(()=>loadSubjects(state.subjectUnit,query),240);}
});
document.addEventListener('change',event=>{
  if(event.target.id==='unit-filter'){state={...state,preferences:{...state.preferences,unit_id:event.target.value},matches:null};persist();history.replaceState(null,'','#/discover');refreshCatalog();}
  if(event.target.id==='source-kind'){const value=event.target.value;state={...state,preferences:{...state.preferences,sourceKind:sourceKinds.some(([key])=>key===value)?value:'catalog'}};persist();return;}
  if(event.target.id==='plan-import-input'){const file=event.target.files?.[0];event.target.value='';readPlanFile(file);return;}
  if(event.target.id==='subject-unit')loadSubjects(event.target.value,state.subjectQuery);
  if(event.target.id==='exam-count'){draftExamCount=Number(event.target.value);draftSubjects=[];document.getElementById('subject-controls').innerHTML=subjectControls();document.getElementById('subject-status').textContent='考试结构已调整，请重新核对科目；取消不会修改已保存条件。';}
  if(/^subject[1-4]$/.test(event.target.name)){const unit=Number(event.target.name.slice(7));const available=[...state.subjectCatalog,...draftSubjects].map(subject=>({...subject,exam_unit:unit}));const chosen=available.find(subject=>subjectIdentity(subject)===event.target.value);draftSubjects=[...draftSubjects.filter(subject=>subject.exam_unit!==unit),...(chosen?[chosen]:[])];}
  if(event.target.matches('[data-compare-id]'))compareProgram(event.target.dataset.compareId);
});
document.addEventListener('keydown',event=>{
  if(event.key==='Tab'){const dialog=document.querySelector('dialog[open]');if(dialog){const controls=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])')].filter(element=>element.tabIndex>=0&&element.getClientRects().length),first=controls[0],last=controls.at(-1);if(first&&((!event.shiftKey&&document.activeElement===last)||(event.shiftKey&&document.activeElement===first)||!dialog.contains(document.activeElement))){event.preventDefault();(event.shiftKey?last:first).focus();}}}
  if(!event.target.matches('[role="tab"]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;if(event.target.closest('.pref-tabs')){event.preventDefault();const tab=event.key==='Home'?'filters':event.key==='End'?'subjects':event.target.dataset.tab==='filters'?'subjects':'filters';prefTab(tab);document.querySelector('.pref-tabs [data-tab="'+tab+'"]').focus();return;}if(event.target.closest('.detail-v2-tabs')){event.preventDefault();const tabs=['overview','history','transfer'],index=tabs.indexOf(event.target.dataset.tab),next=nextTabIndex(event.key,index,tabs.length);if(next>=0)actions['detail-tab']({dataset:{tab:tabs[next]}});}
});
for(const dialog of document.querySelectorAll('dialog')){dialog.addEventListener('close',()=>{if(dialog.id==='preferences-dialog'){subjectController?.abort();}if(dialog.id==='info-dialog'){collectionCleanup?.();collectionCleanup=undefined;resetProfileRequested=false;pendingPlanImport=null;}if(dialog.id==='evidence-dialog'){++evidenceGeneration;evidenceCleanup?.();evidenceCleanup=undefined;}document.body.style.overflow=document.querySelector('dialog[open]')?'hidden':'';});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();});}
